arguments.command:
cat << 'EOF' > /app/output/index.html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    /* ===== CSS RESET & BASE ===== */
    *, *::before, *::after {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    :root {
      /* OKLCH Color System */
      --color-primary: oklch(20% 0.02 280);       /* Near-black */
      --color-accent-purple: oklch(58% 0.22 285); /* #7638FA equivalent */
      --color-accent-orange: oklch(70% 0.18 55);  /* #FF7A00 equivalent */
      --color-accent-magenta: oklch(65% 0.24 330); /* Vibrant magenta */
      --color-text-primary: oklch(20% 0.02 280);
      --color-text-secondary: oklch(45% 0.03 280);
      --color-text-muted: oklch(60% 0.04 280);
      --color-bg: oklch(98% 0.005 280);
      --color-bg-surface: oklch(100% 0 0);
      --color-bg-muted: oklch(95% 0.01 280);
      --color-border: oklch(88% 0.02 280);
      --color-safety: oklch(55% 0.12 195);        /* Teal for safety */
      --color-creators: oklch(60% 0.18 300);      /* Purple for creators */

      /* Spacing Scale (8px base) */
      --space-1: 4px;
      --space-2: 8px;
      --space-3: 16px;
      --space-4: 24px;
      --space-5: 32px;
      --space-6: 48px;
      --space-7: 64px;
      --space-8: 96px;

      /* Typography */
      --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
      --font-body: 'Inter', system-ui, sans-serif;

      /* Radius */
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-full: 9999px;

      /* Shadows */
      --shadow-sm: 0 1px 2px 0 oklch(0% 0 0 / 0.05);
      --shadow-md: 0 4px 6px -1px oklch(0% 0 0 / 0.1), 0 2px 4px -2px oklch(0% 0 0 / 0.1);
      --shadow-lg: 0 10px 15px -3px oklch(0% 0 0 / 0.1), 0 4px 6px -4px oklch(0% 0 0 / 0.1);
      --shadow-xl: 0 20px 25px -5px oklch(0% 0 0 / 0.1), 0 8px 10px -6px oklch(0% 0 0 / 0.1);

      /* Transitions */
      --transition-fast: 150ms ease;
      --transition-base: 250ms ease;
      --transition-slow: 350ms ease;
    }

    html {
      scroll-behavior: smooth;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    body {
      font-family: var(--font-body);
      color: var(--color-text-primary);
      background: var(--color-bg);
      line-height: 1.6;
      overflow-x: hidden;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    img {
      max-width: 100%;
      display: block;
    }

    button {
      font-family: inherit;
      cursor: pointer;
      border: none;
      background: none;
    }

    ul, ol {
      list-style: none;
    }

    /* ===== UTILITIES ===== */
    .container {
      width: 100%;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 var(--space-3);
    }

    @media (min-width: 640px) {
      .container {
        padding: 0 var(--space-4);
      }
    }

    @media (min-width: 1024px) {
      .container {
        padding: 0 var(--space-5);
      }
    }

    /* ===== HEADER ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: oklch(100% 0 0 / 0.85);
      backdrop-filter: blur(20px) saturate(180%);
      -webkit-backdrop-filter: blur(20px) saturate(180%);
      border-bottom: 1px solid var(--color-border);
      transition: box-shadow var(--transition-base);
    }

    .header.scrolled {
      box-shadow: var(--shadow-md);
    }

    .header__inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .header__logo {
      font-family: var(--font-heading);
      font-weight: 800;
      font-size: 1.5rem;
      letter-spacing: -0.03em;
      color: var(--color-primary);
      display: flex;
      align-items: center;
      gap: var(--space-2);
    }

    .header__logo-icon {
      width: 32px;
      height: 32px;
      background: linear-gradient(135deg, var(--color-accent-purple), var(--color-accent-magenta));
      border-radius: var(--radius-md);
      display: grid;
      place-items: center;
      color: white;
      font-size: 14px;
    }

    .header__nav-desktop {
      display: none;
      align-items: center;
      gap: var(--space-5);
    }

    .header__nav-link {
      font-size: 0.9375rem;
      font-weight: 500;
      color: var(--color-text-secondary);
      transition: color var(--transition-fast);
      position: relative;
    }

    .header__nav-link:hover {
      color: var(--color-text-primary);
    }

    .header__nav-link::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--color-accent-purple);
      transition: width var(--transition-fast);
      border-radius: var(--radius-full);
    }

    .header__nav-link:hover::after {
      width: 100%;
    }

    .header__actions {
      display: flex;
      align-items: center;
      gap: var(--space-3);
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: var(--space-2);
      padding: 10px 20px;
      font-size: 0.9375rem;
      font-weight: 600;
      border-radius: var(--radius-full);
      transition: all var(--transition-fast);
      white-space: nowrap;
    }

    .btn--primary {
      background: var(--color-primary);
      color: white;
    }

    .btn--primary:hover {
      background: oklch(30% 0.03 280);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .btn--outline {
      background: transparent;
      color: var(--color-text-primary);
      border: 1.5px solid var(--color-border);
    }

    .btn--outline:hover {
      border-color: var(--color-text-secondary);
      background: var(--color-bg-muted);
    }

    .btn--gradient {
      background: linear-gradient(135deg, var(--color-accent-purple), var(--color-accent-magenta));
      color: white;
      border: none;
    }

    .btn--gradient:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 25px oklch(58% 0.22 285 / 0.35);
    }

    .hamburger {
      width: 40px;
      height: 40px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 5px;
      border-radius: var(--radius-md);
      transition: background var(--transition-fast);
    }

    .hamburger:hover {
      background: var(--color-bg-muted);
    }

    .hamburger__line {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--color-text-primary);
      border-radius: var(--radius-full);
      transition: all var(--transition-base);
    }

    .hamburger.active .hamburger__line:nth-child(1) {
      transform: translateY(7px) rotate(45deg);
    }

    .hamburger.active .hamburger__line:nth-child(2) {
      opacity: 0;
    }

    .hamburger.active .hamburger__line:nth-child(3) {
      transform: translateY(-7px) rotate(-45deg);
    }

    /* Mobile Navigation Overlay */
    .mobile-nav {
      position: fixed;
      inset: 0;
      z-index: 999;
      background: var(--color-bg);
      display: flex;
      flex-direction: column;
      padding: 80px var(--space-4) var(--space-4);
      transform: translateX(100%);
      transition: transform var(--transition-slow);
    }

    .mobile-nav.active {
      transform: translateX(0);
    }

    .mobile-nav__link {
      font-family: var(--font-heading);
      font-size: 1.5rem;
      font-weight: 700;
      padding: var(--space-3) 0;
      border-bottom: 1px solid var(--color-border);
      color: var(--color-text-primary);
      transition: color var(--transition-fast);
    }

    .mobile-nav__link:hover {
      color: var(--color-accent-purple);
    }

    .mobile-nav__actions {
      margin-top: auto;
      display: flex;
      flex-direction: column;
      gap: var(--space-3);
    }

    .mobile-nav .btn {
      width: 100%;
      padding: 14px;
      font-size: 1rem;
    }

    @media (min-width: 768px) {
      .hamburger {
        display: none;
      }

      .header__nav-desktop {
        display: flex;
      }
    }

    /* ===== HERO ===== */
    .hero {
      position: relative;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      text-align: center;
      padding: 120px var(--space-3) var(--space-8);
      overflow: hidden;
    }

    .hero__bg {
      position: absolute;
      inset: 0;
      z-index: 0;
    }

    .hero__bg-gradient {
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 80% 60% at 50% 40%, oklch(75% 0.15 300 / 0.25) 0%, transparent 60%),
        radial-gradient(ellipse 60% 50% at 80% 20%, oklch(80% 0.12 45 / 0.2) 0%, transparent 50%),
        radial-gradient(ellipse 50% 40% at 20% 80%, oklch(70% 0.15 285 / 0.2) 0%, transparent 50%),
        linear-gradient(180deg, var(--color-bg) 0%, oklch(97% 0.01 280) 100%);
    }

    .hero__bg-shapes {
      position: absolute;
      inset: 0;
      overflow: hidden;
    }

    .hero__shape {
      position: absolute;
      border-radius: 50%;
      filter: blur(60px);
      opacity: 0.5;
      animation: float 8s ease-in-out infinite;
    }

    .hero__shape--1 {
      width: 400px;
      height: 400px;
      background: var(--color-accent-purple);
      top: -10%;
      left: -10%;
      animation-delay: 0s;
    }

    .hero__shape--2 {
      width: 300px;
      height: 300px;
      background: var(--color-accent-orange);
      top: 20%;
      right: -5%;
      animation-delay: -2s;
    }

    .hero__shape--3 {
      width: 350px;
      height: 350px;
      background: var(--color-accent-magenta);
      bottom: -5%;
      left: 30%;
      animation-delay: -4s;
    }

    @keyframes float {
      0%, 100% { transform: translate(0, 0) scale(1); }
      33% { transform: translate(30px, -30px) scale(1.05); }
      66% { transform: translate(-20px, 20px) scale(0.95); }
    }

    .hero__content {
      position: relative;
      z-index: 1;
      max-width: 800px;
    }

    .hero__eyebrow {
      display: inline-flex;
      align-items: center;
      gap: var(--space-2);
      padding: 6px 14px;
      background: oklch(95% 0.02 280);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-full);
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--color-accent-purple);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: var(--space-4);
    }

    .hero__title {
      font-family: var(--font-heading);
      font-size: clamp(2.25rem, 6vw, 4.5rem);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.03em;
      color: var(--color-primary);
      margin-bottom: var(--space-4);
    }

    .hero__title span {
      background: linear-gradient(135deg, var(--color-accent-purple), var(--color-accent-magenta), var(--color-accent-orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero__subtitle {
      font-size: clamp(1rem, 2vw, 1.25rem);
      color: var(--color-text-secondary);
      max-width: 560px;
      margin: 0 auto var(--space-5);
      line-height: 1.7;
    }

    .hero__cta {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: var(--space-3);
    }

    .hero__cta .btn {
      padding: 14px 32px;
      font-size: 1rem;
    }

    @media (min-width: 480px) {
      .hero__cta {
        flex-direction: row;
        justify-content: center;
      }
    }

    /* ===== SECTIONS COMMON ===== */
    .section {
      padding: var(--space-7) 0;
    }

    .section__label {
      font-size: 0.8125rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--color-accent-purple);
      margin-bottom: var(--space-2);
    }

    .section__heading {
      font-family: var(--font-heading);
      font-size: clamp(1.75rem, 4vw, 2.75rem);
      font-weight: 800;
      line-height: 1.15;
      letter-spacing: -0.02em;
      color: var(--color-primary);
      margin-bottom: var(--space-3);
    }

    .section__text {
      font-size: 1.0625rem;
      color: var(--color-text-secondary);
      line-height: 1.7;
      max-width: 560px;
    }

    .section__link {
      display: inline-flex;
      align-items: center;
      gap: var(--space-1);
      font-size: 1rem;
      font-weight: 600;
      color: var(--color-accent-purple);
      margin-top: var(--space-3);
      transition: gap var(--transition-fast);
    }

    .section__link:hover {
      gap: var(--space-2);
    }

    .section__link svg {
      width: 18px;
      height: 18px;
    }

    /* ===== FEATURES ===== */
    .features {
      background: var(--color-bg-surface);
    }

    .features__inner {
      display: grid;
      grid-template-columns: 1fr;
      gap: var(--space-5);
      align-items: center;
    }

    .features__visual {
      position: relative;
      border-radius: var(--radius-xl);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, oklch(92% 0.06 285), oklch(95% 0.04 300));
    }

    .features__visual-content {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: var(--space-4);
    }

    .features__phone-mockup {
      width: 180px;
      height: 340px;
      background: var(--color-primary);
      border-radius: 24px;
      padding: 8px;
      box-shadow: var(--shadow-xl);
      transform: rotate(-6deg);
    }

    .features__phone-screen {
      width: 100%;
      height: 100%;
      background: linear-gradient(180deg, oklch(30% 0.08 285), oklch(25% 0.06 300));
      border-radius: 18px;
      overflow: hidden;
      position: relative;
    }

    .features__phone-screen::before {
      content: '';
      position: absolute;
      top: 20px;
      left: 16px;
      right: 16px;
      height: 120px;
      background: linear-gradient(135deg, var(--color-accent-purple), var(--color-accent-magenta));
      border-radius: var(--radius-md);
    }

    .features__phone-screen::after {
      content: '';
      position: absolute;
      bottom: 20px;
      left: 16px;
      right: 16px;
      height: 60px;
      background: oklch(35% 0.05 280);
      border-radius: var(--radius-md);
    }

    @media (min-width: 768px) {
      .features__inner {
        grid-template-columns: 1fr 1fr;
        gap: var(--space-7);
      }
    }

    /* ===== SAFETY ===== */
    .safety {
      background: linear-gradient(180deg, var(--color-bg-surface) 0%, oklch(97% 0.01 195) 100%);
    }

    .safety__inner {
      display: grid;
      grid-template-columns: 1fr;
      gap: var(--space-5);
      align-items: center;
    }

    .safety__visual {
      position: relative;
      border-radius: var(--radius-xl);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, oklch(92% 0.04 195), oklch(95% 0.03 200));
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .safety__shield {
      width: 140px;
      height: 160px;
      background: linear-gradient(180deg, var(--color-safety), oklch(45% 0.1 195));
      border-radius: 0 0 70px 70px;
      display: grid;
      place-items: center;
      box-shadow: var(--shadow-lg);
    }

    .safety__shield svg {
      width: 60px;
      height: 60px;
      color: white;
    }

    @media (min-width: 768px) {
      .safety__inner {
        grid-template-columns: 1fr 1fr;
        gap: var(--space-7);
      }

      .safety__content {
        order: 2;
      }

      .safety__visual {
        order: 1;
      }
    }

    /* ===== CREATORS ===== */
    .creators {
      background: linear-gradient(180deg, oklch(97% 0.01 195) 0%, oklch(96% 0.02 300) 100%);
    }

    .creators__inner {
      display: grid;
      grid-template-columns: 1fr;
      gap: var(--space-5);
      align-items: center;
    }

    .creators__visual {
      position: relative;
      border-radius: var(--radius-xl);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: linear-gradient(135deg, oklch(90% 0.08 300), oklch(93% 0.06 285));
      display: flex;
      align-items: center;
      justify-content: center;
      gap: var(--space-3);
    }

    .creators__card {
      width: 120px;
      height: 160px;
      background: var(--color-bg-surface);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      padding: var(--space-3);
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: var(--space-2);
    }

    .creators__card-avatar {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--color-accent-purple), var(--color-accent-magenta));
    }

    .creators__card-line {
      width: 100%;
      height: 8px;
      background: var(--color-bg-muted);
      border-radius: var(--radius-full);
    }

    .creators__card-line--short {
      width: 60%;
    }

    .creators__card:nth-child(1) {
      transform: rotate(-8deg) translateY(-10px);
    }

    .creators__card:nth-child(2) {
      transform: rotate(4deg) translateY(10px);
      z-index: 1;
    }

    .creators__card:nth-child(3) {
      transform: rotate(-3deg) translateY(-5px);
    }

    @media (min-width: 768px) {
      .creators__inner {
        grid-template-columns: 1fr 1fr;
        gap: var(--space-7);
      }
    }

    /* ===== TAGLINE BANNER ===== */
    .tagline {
      background: var(--color-primary);
      padding: var(--space-7) 0;
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .tagline__text {
      font-family: var(--font-heading);
      font-size: clamp(1.5rem, 4vw, 2.5rem);
      font-weight: 800;
      color: white;
      letter-spacing: -0.02em;
      position: relative;
      z-index: 1;
    }

    .tagline__gradient {
      background: linear-gradient(135deg, var(--color-accent-purple), var(--color-accent-magenta), var(--color-accent-orange));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .tagline__bg {
      position: absolute;
      inset: 0;
      opacity: 0.1;
      background:
        radial-gradient(circle at 20% 50%, var(--color-accent-purple) 0%, transparent 50%),
        radial-gradient(circle at 80% 50%, var(--color-accent-magenta) 0%, transparent 50%);
    }

    /* ===== NEWS CAROUSEL ===== */
    .news {
      background: var(--color-bg-surface);
      padding: var(--space-7) 0;
    }

    .news__header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      margin-bottom: var(--space-5);
    }

    .news__carousel {
      display: flex;
      gap: var(--space-4);
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scroll-behavior: smooth;
      -webkit-overflow-scrolling: touch;
      padding-bottom: var(--space-3);
      margin: 0 calc(-1 * var(--space-3));
      padding-left: var(--space-3);
      padding-right: var(--space-3);
      scrollbar-width: none;
    }

    .news__carousel::-webkit-scrollbar {
      display: none;
    }

    .news__card {
      flex: 0 0 280px;
      scroll-snap-align: start;
      background: var(--color-bg-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: transform var(--transition-base), box-shadow var(--transition-base);
      cursor: pointer;
    }

    .news__card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-xl);
    }

    .news__card-thumb {
      aspect-ratio: 16/10;
      background: linear-gradient(135deg, oklch(90% 0.06 285), oklch(88% 0.08 300));
      position: relative;
      overflow: hidden;
    }

    .news__card-thumb::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(180deg, transparent 50%, oklch(0% 0 0 / 0.3) 100%);
    }

    .news__card-content {
      padding: var(--space-3);
    }

    .news__card-tags {
      display: flex;
      flex-wrap: wrap;
      gap: var(--space-1);
      margin-bottom: var(--space-2);
    }

    .news__card-tag {
      font-size: 0.6875rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      padding: 4px 10px;
      border-radius: var(--radius-full);
      background: oklch(95% 0.02 280);
      color: var(--color-accent-purple);
    }

    .news__card-title {
      font-family: var(--font-heading);
      font-size: 1rem;
      font-weight: 700;
      line-height: 1.4;
      color: var(--color-text-primary);
      margin-bottom: var(--space-2);
      display: -webkit-box;
